252	function renderChart(month) {
253	  if (!chartCanvas || typeof chartCanvas.getContext !== 'function') return;
254	  const ctx = chartCanvas.getContext('2d');
255	  if (!ctx) return;
256	
257	  const width = chartCanvas.width || 600;
258	  const height = chartCanvas.height || 300;
259	  ctx.clearRect(0, 0, width, height);
260	
261	  // Calculate expenses per category in that month
262	  const expenseByCat = {};
263	  for (const item of transactions) {
264	    if (month && (!item.date || !item.date.startsWith(month))) continue;
265	    const amt = Number(item.amount) || 0;
266	    if (amt < 0) {
267	      expenseByCat[item.category] = (expenseByCat[item.category] || 0) + -amt;
268	    }
269	  }
270	
271	  const entries = Object.entries(expenseByCat).filter(([, val]) => val > 0);
272	  if (entries.length === 0) return;
273	
274	  const maxExpense = Math.max(...entries.map(([, val]) => val), 1);
275	  const padding = 30;
276	  const chartW = width - padding * 2;
277	  const chartH = height - padding * 2;
278	  const slotW = chartW / entries.length;
279	  const barW = Math.max(10, slotW * 0.6);
280	
281	  entries.forEach(([cat, val], idx) => {
282	    const barH = Math.max(2, (val / maxExpense) * chartH);
283	    const x = padding + idx * slotW + (slotW - barW) / 2;
284	    const y = height - padding - barH;
285	
286	    ctx.fillStyle = '#2563eb';
287	    ctx.fillRect(x, y, barW, barH);
288	
289	    ctx.fillStyle = '#0f172a';
290	    ctx.font = '12px sans-serif';
291	    ctx.fillText(`${cat} (${val.toFixed(2)})`, x, height - 10);
292	  });
293	}
