// Returns the 'YYYY-MM' month `delta` months away from `month`
function shiftMonth(month, delta) {
  const [y, m] = month.split('-').map(Number);
  const total = y * 12 + (m - 1) + delta;
  const year = Math.floor(total / 12);
  const mon = (total % 12) + 1;
  return `${String(year).padStart(4, '0')}-${String(mon).padStart(2, '0')}`;
}

// Formats a difference with a sign and two decimals, e.g. +12.50, -20.00, 0.00
function formatChange(diff) {
  const cents = Math.round(diff * 100) / 100;
  if (cents === 0) return '0.00';
  return (cents > 0 ? '+' : '') + cents.toFixed(2);
}

function renderReports() {
  if (!reportBody) return;
  const month = (reportMonthInput && reportMonthInput.value) || getDefaultMonth();
  const range = month ? { from: `${month}-01`, to: `${month}-31` } : undefined;
  const summary = summarize(transactions, range);

  const prevMonth = month ? shiftMonth(month, -1) : '';
  const prevRange = month ? { from: `${prevMonth}-01`, to: `${prevMonth}-31` } : undefined;
  const prevSummary = summarize(transactions, prevRange);

  reportBody.innerHTML = '';
  const categories = Object.keys(summary.byCategory);
  // Categories that only had transactions in the previous month still get a row
  for (const cat of Object.keys(prevSummary.byCategory)) {
    if (!Object.prototype.hasOwnProperty.call(summary.byCategory, cat)) {
      categories.push(cat);
    }
  }
  for (const cat of categories) {
    const total = summary.byCategory[cat] || 0;
    const prevTotal = prevSummary.byCategory[cat] || 0;

    const tr = document.createElement('tr');

    const tdCat = document.createElement('td');
    tdCat.textContent = cat;

    const tdTotal = document.createElement('td');
    tdTotal.textContent = Number(total).toFixed(2);

    const tdChange = document.createElement('td');
    tdChange.textContent = formatChange(total - prevTotal);

    tr.appendChild(tdCat);
    tr.appendChild(tdTotal);
    tr.appendChild(tdChange);
    reportBody.appendChild(tr);
  }

