    const barH = Math.max(2, (val / maxExpense) * chartH);
    const x = padding + idx * slotW + (slotW - barW) / 2;
    const y = height - padding - barH;

    ctx.fillStyle = '#2563eb';
    ctx.fillRect(x, y, barW, barH);

    ctx.fillStyle = '#0f172a';
