function loadTransactions() {
  try {
    const raw = localStorage.getItem(STORAGE_TX_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

