function renderBalance() {
  if (!balanceEl) return;
  const { balance } = summarize(transactions);
  const cents = Math.round(balance * 100) / 100;
  // `|| 0` turns -0 into 0 so it is not shown as "-0.00"
  balanceEl.textContent = (cents || 0).toFixed(2);
