function updateEditControls() {
  const editing = editingIndex !== null;
  if (addBtn) addBtn.textContent = editing ? 'Save' : 'Add';
  if (cancelEditBtn) cancelEditBtn.hidden = !editing;
}

function startEdit(index) {
  const item = transactions[index];
  if (!item) return;
  if (dateInput) dateInput.value = item.date || '';
  if (descriptionInput) descriptionInput.value = item.description || '';
  if (amountInput) amountInput.value = String(item.amount);
  if (categoryInput) categoryInput.value = item.category || '';
  // Edits always save a single transaction, so reset the recurrence fields
  if (repeatSelect) repeatSelect.value = 'none';
  if (untilInput) untilInput.value = '';
  editingIndex = index;
  updateEditControls();
}

function exitEditMode() {
  if (editingIndex === null) return;
  editingIndex = null;
  for (const el of [dateInput, descriptionInput, amountInput, categoryInput, untilInput]) {
    if (el) el.value = '';
  }
  if (repeatSelect) repeatSelect.value = 'none';
  updateEditControls();
}

